syntax:
type **array_name; // Pointer to an array of pointers
// Initialization with memory allocation:
for (int j = 0; j < N; j++) {
    array_name[j] = malloc(size_in_bytes);
}

code_example:
char *display[5]; // Array of pointers to strings
for (int j = 0; j < 5; j++) {
    display[j] = malloc(6); // Allocate memory for each string
    strcpy(display[j], "hello"); // Initialize string data
}
